    "/v1/mailbox/webhook": {
      "get": {
        "tags": [
          "mailbox"
        ],
        "summary": "Webhook Read",
        "description": "Your subscription and the result of the last 20 pushes (the secret is not shown).\n\n`state` of a push: `queued`, `sending`, `retrying`, `delivered` or `failed`. `error`\nsays what went wrong on the last try. 404 if you have no subscription.",
