          "200": {
            "description": "Successful Response",
            "content": {
              "application/json": {
                "schema": {
                  "additionalProperties": true,
                  "type": "object",
                  "title": "Response Webhook Subscribe V1 Mailbox Webhook Put"
                }
              }
            }
          },
          "422": {
            "description": "Validation Error",
            "content": {
              "application/json": {
                "schema": {
                  "$ref": "#/components/schemas/HTTPValidationError"
                }
              }
            }
          }
        },
        "security": [
          {
            "Team key": []
          }
        ]
      },
      "delete": {
        "tags": [
          "mailbox"
        ],
        "summary": "Webhook Unsubscribe",
        "description": "Stop the pushes. Your mail stays in the mailbox. 404 if you have no subscription.",
        "operationId": "webhook_unsubscribe_v1_mailbox_webhook_delete",
        "responses": {
          "204": {
            "description": "Successful Response"
          }
        },
        "security": [
          {
            "Team key": []
          }
        ]
      }
    },
    "/v1/mailbox/webhook/test": {
      "post": {
        "tags": [
          "mailbox"
        ],
        "summary": "Webhook Test",
        "description": "Send one signed test call to your endpoint now and tell you how it went.\n\nThe body is `{\"event\": \"ping\", \"team\": \"<your team>\"}`, signed like a real push.\nThe answer: `delivered`, your endpoint's `status_code` and an `error` text. One test\nevery few seconds. 404 if you have no subscription.",
        "operationId": "webhook_test_v1_mailbox_webhook_test_post",
        "responses": {
          "200": {
            "description": "Successful Response",
            "content": {
              "application/json": {
                "schema": {
